function fit(){const r=viewport.getBoundingClientRect();zoom=clamp(Math.min((r.width-(r.width<400?36:110))/doc.width,(r.height-100)/doc.height),.005,4);pan={x:0,y:0};positionCanvas();}
function changeZoom(factor){zoom=clamp(zoom*factor,.005,4);positionCanvas();}
function updateSelection(){const multi=selectedIds.size>1,l=multi?selectionBounds():selected(),box=$('#selectionBox');if(!l||!l.visible||editing||tool==='brush'||tool==='shape'||tool==='region'){box.style.display='none';return;}box.style.cssText=`display:block;left:${l.x}px;top:${l.y}px;width:${l.w}px;height:${l.h}px;transform:rotate(${l.rotation}deg);border-width:${1.2/zoom}px`;box.classList.toggle('locked',l.locked);$$('button',box).forEach(el=>{el.style.display=l.locked||multi||tool==='marquee'?'none':'';el.style.width=8/zoom+'px';el.style.height=8/zoom+'px';el.style.borderWidth=1.2/zoom+'px';});$('.rotation-stem',box).style.display=multi||tool==='marquee'?'none':'';$('.rotation-stem',box).style.height=22/zoom+'px';$('.rotation-stem',box).style.top=-22/zoom+'px';$('.rotate-handle',box).style.top=-27/zoom+'px';$('#selectionSize').textContent=multi?`已选中 ${selectedIds.size} 个元素`:`${Math.round(l.w)} × ${Math.round(l.h)}`;$('#selectionSize').style.fontSize=9/zoom+'px';$('#selectionSize').style.bottom=-25/zoom+'px';$('#selectionSize').style.padding=`${3/zoom}px ${7/zoom}px`;}
function select(id,additive=false){finishTextEdit();const ids=additive?new Set(selectedIds):new Set();if(id){if(additive&&ids.has(id))ids.delete(id);else ids.add(id);}setSelection([...ids]);textRange=null;render();renderInspector();if(activePanel==='layers')renderAssets();}
function addLayer(l){doc.layers.push(l);setSelection([l.id]);textRange=null;setTool('select');commit();refresh();$('#assetPanel').classList.remove('mobile-open');}
function addText(kind='heading'){const size=kind==='heading'?64:kind==='subheading'?36:22;addLayer(textLayer(kind==='heading'?'写下你的灵感':kind==='subheading'?'让美好，慢慢发生。':'在这里，记录你的故事。',doc.width*.15,doc.height*.38,doc.width*.7,size,{bold:kind==='heading',h:size*1.8}));toast('已添加文字 · 双击文字框即可编辑');}
const shapeNames={rect:'矩形',roundrect:'圆角矩形',ellipse:'圆形',triangle:'三角形',line:'直线',arrow:'块状箭头',lineArrow:'线条箭头',star:'五角星',heart:'爱心',sparkle:'星芒'};
function addShape(shape){select(null);pendingShape=shape;setTool('shape');renderAssets();$('#assetPanel').classList.remove('mobile-open');$('#drawingHint').textContent=`${shapeNames[shape]} · 在画布上拖动绘制，Shift 等比 / 限定角度，Esc 取消`;}
function cancelShapeDrawing(){if(drag?.type!=='shape')return;const current=drag;if(current.drawn)doc.layers=doc.layers.filter(l=>l.id!==current.draft.id);drag=null;setSelection(current.previous);try{viewport.releasePointerCapture(current.pointer);}catch{}render();persist();renderInspector();}
function updateShapeDrawing(point,shift){
 const start=drag.start,end={x:clamp(point.x,0,doc.width),y:clamp(point.y,0,doc.height)};
 let dx=end.x-start.x,dy=end.y-start.y;
 if(!drag.drawn&&Math.hypot(dx,dy)*zoom<3)return;
 const l=drag.draft,directional=l.shape==='line'||l.shape==='arrow'||l.shape==='lineArrow';
 if(directional){
  let angle=Math.atan2(dy,dx),length=Math.hypot(dx,dy);
  if(shift){angle=Math.round(angle/(Math.PI/4))*Math.PI/4;dx=Math.cos(angle)*length;dy=Math.sin(angle)*length;}
  const ex=clamp(start.x+dx,0,doc.width),ey=clamp(start.y+dy,0,doc.height);
  dx=ex-start.x;dy=ey-start.y;l.w=Math.max(1,Math.hypot(dx,dy));l.h=l.shape==='line'?2:clamp(l.w*.25,8,80);l.rotation=Math.atan2(dy,dx)*180/Math.PI;l.x=(start.x+ex)/2-l.w/2;l.y=(start.y+ey)/2-l.h/2;
 }else{
  if(shift){const sx=dx<0?-1:1,sy=dy<0?-1:1;const size=Math.min(Math.max(Math.abs(dx),Math.abs(dy)),sx>0?doc.width-start.x:start.x,sy>0?doc.height-start.y:start.y);dx=sx*size;dy=sy*size;}
  l.x=Math.min(start.x,start.x+dx);l.y=Math.min(start.y,start.y+dy);l.w=Math.max(1,Math.abs(dx));l.h=Math.max(1,Math.abs(dy));if(l.shape==='roundrect')l.radius=Math.min(32,l.w/5,l.h/5);
 }
 if(!drag.drawn){doc.layers.push(l);drag.drawn=true;setSelection([l.id]);}
 render();$('#drawingHint').textContent=`${shapeNames[l.shape]} · ${Math.round(l.w)} × ${Math.round(l.h)} px`;
}
function finishShapeDrawing(e){
 if(e.type==='pointercancel'){cancelShapeDrawing();return;}
 updateShapeDrawing(toCanvas(e),e.shiftKey);const drawn=drag.drawn,pointer=drag.pointer;drag=null;try{viewport.releasePointerCapture(pointer);}catch{}
 if(drawn){setTool('select');commit();refresh();}else{$('#drawingHint').textContent=`${shapeNames[pendingShape]} · 拖动绘制，点击不会添加图形`;}
}
function duplicate(){const copies=selectedLayers().filter(l=>!l.locked).map(l=>({...clone(l),id:uid(),x:l.x+20,y:l.y+20,locked:false,name:l.name+' 副本'}));if(!copies.length)return;doc.layers.push(...copies);setSelection(copies.map(l=>l.id));textRange=null;commit();refresh();toast(`已复制 ${copies.length} 个图层`);}
function remove(){const ids=new Set(selectedLayers().filter(l=>!l.locked).map(l=>l.id));if(!ids.size){if(selected())toast('请先解锁此图层');return;}doc.layers=doc.layers.filter(l=>!ids.has(l.id));setSelection([]);commit();refresh();}
function reorder(direction){if(selectedIds.size>1){toast('请先选择单个图层调整顺序');return;}const l=selected();if(!l)return;const i=doc.layers.indexOf(l),next=clamp(i+direction,0,doc.layers.length-1);doc.layers.splice(i,1);doc.layers.splice(next,0,l);commit();render();renderAssets();}
function backgroundSwatches(){return `<div class="background-swatches">${[['#ffffff','白色'],['#f3f0e5','米白'],['#e5c9a5','浅杏'],['#243d3b','墨绿']].map(([color,name])=>`<button data-background="${color}" class="background-swatch ${doc.background.toLowerCase()===color?'active':''}" aria-label="背景设为${name}" title="${name}" style="--swatch:${color}"><span>${doc.background.toLowerCase()===color?'✓':''}</span><small>${name}</small></button>`).join('')}</div>`;}
function updateRegionSelection(){if(region){region.x=clamp(region.x,0,doc.width);region.y=clamp(region.y,0,doc.height);region.w=Math.min(region.w,doc.width-region.x);region.h=Math.min(region.h,doc.height-region.y);if(region.w<=0||region.h<=0)region=null;}const el=$('#regionSelection');if(!el)return;if(tool!=='region'||!region){el.style.display='none';return;}el.style.cssText=`display:block;left:${region.x}px;top:${region.y}px;width:${region.w}px;height:${region.h}px;border-width:${1/zoom}px`;$('#regionHint').textContent=`${region.w} × ${region.h} px · 按 Delete 填充为背景色`;}
function updateRegion(point){const end={x:clamp(point.x,0,doc.width),y:clamp(point.y,0,doc.height)},start=drag.start;const x=Math.round(Math.min(start.x,end.x)),y=Math.round(Math.min(start.y,end.y));const right=Math.round(Math.max(start.x,end.x)),bottom=Math.round(Math.max(start.y,end.y));region=right>x&&bottom>y?{x,y,w:right-x,h:bottom-y}:null;updateRegionSelection();}
function finishRegion(e){const current=drag;if(e.type==='pointercancel')region=current.previous;else updateRegion(toCanvas(e));drag=null;try{viewport.releasePointerCapture(current.pointer);}catch{}updateRegionSelection();renderInspector();}
function fillRegion(){if(!region){toast('请先在画布上拖动选择要清除的区域');return;}const r=region;doc.layers.push({...baseLayer('shape','区域填充',r.x,r.y,r.w,r.h),shape:'rect',fill:doc.background,fillEnabled:true,backgroundFill:true,strokeWidth:0});region=null;setSelection([]);commit();refresh();$('#regionHint').textContent='已填充为背景色 · 继续拖动选择区域，Esc 取消';toast('已用背景色填充选区，可撤销');}
const uploadCard=()=>`<button class="upload-card" data-action="upload"><span class="upload-icon">${icon('upload')}</span><strong>上传你的图片</strong><small>拖拽到画布，或点击上传</small><small>JPG / PNG / WebP · 最大 15 MB</small></button>`;
function renderAssets(){const panel=$('#assetPanel');const heading=(title,sub,extra='')=>`<div class="panel-heading"><h2>${title}</h2><span>${extra}</span></div><p class="panel-subtitle">${sub}</p>`;
 if(activePanel==='elements'){panel.innerHTML=heading('创作，从这里开始','让每一个小灵感，都有形状。')+uploadCard()+`<div class="section-heading">文字<span>表达你的想法</span></div><button class="add-text-button" data-action="add-text">${icon('type')}添加文字<span>+</span></button><div class="section-heading">基础图形<span>选择后拖动绘制</span></div><div class="shape-grid">${Object.entries(shapeNames).slice(0,7).map(([key,name])=>`<button class="shape-tile ${tool==='shape'&&pendingShape===key?'active':''}" data-shape="${key}" aria-pressed="${tool==='shape'&&pendingShape===key}">${icon(key)}<span>${name}</span></button>`).join('')}</div><div class="section-heading">画布背景<span>独立于图形颜色</span></div>${backgroundSwatches()}`;
 }else if(activePanel==='text'){panel.innerHTML=heading('文字的力量','给灵感，一个恰好的表达。')+`<button class="add-text-button" data-action="add-text">${icon('plus')}添加文字框<span>T</span></button><div class="section-heading">文字样式<span>点击添加</span></div><button class="text-preset heading" data-text="heading">添加大标题</button><button class="text-preset subheading" data-text="subheading">添加副标题</button><button class="text-preset body" data-text="body">添加一段正文，记录此刻的灵感。</button><div class="section-heading">你的字体<button class="mini-link" data-action="font">${icon('plus')}导入字体</button></div><p class="panel-subtitle">支持 TTF、OTF、WOFF 和 WOFF2。字体会随项目一起保存。</p><div class="asset-note">${icon('type')}双击文字框即可编辑。选中部分文字，可单独调整字重、字体与颜色。</div>`;
 }else if(activePanel==='images'){panel.innerHTML=heading('你的影像','把喜欢的瞬间，放进作品里。')+uploadCard()+`<div class="section-heading">最近上传<span>${uploads.length} 张</span></div><div class="upload-thumbnails">${uploads.map((src,i)=>`<button data-upload-index="${i}" title="再次添加图片"><img src="${esc(src)}" alt="已上传的图片 ${i+1}"></button>`).join('')}</div>${uploads.length?'':`<div class="empty-state">${icon('image')}<br>你的图片，会出现在这里。</div>`}`;
 }else{panel.innerHTML=heading('图层管理','让每个元素，都在对的位置。',`${doc.layers.length} 个图层`)+`<div class="layer-order"><button data-action="layer-up">${icon('up')}上移一层</button><button data-action="layer-down">${icon('down')}下移一层</button></div><div class="layer-list">${[...doc.layers].reverse().map(l=>`<div class="layer-row ${selectedIds.has(l.id)?'active':''} ${!l.visible?'muted':''}" data-layer="${l.id}" role="button" tabindex="0" aria-label="选择图层 ${esc(l.name)}"><span class="layer-thumb" style="color:${esc(l.fill)}">${l.type==='image'?`<img src="${esc(l.src)}" alt="">`:icon(l.type==='text'?'type':l.type==='path'?'pen':l.shape)}</span><span class="layer-name">${esc(l.name)}</span><button data-layer-lock="${l.id}" title="${l.locked?'解锁':'锁定'}" aria-label="${l.locked?'解锁':'锁定'} ${esc(l.name)}">${icon(l.locked?'lock':'unlock')}</button><button data-layer-visibility="${l.id}" title="${l.visible?'隐藏':'显示'}" aria-label="${l.visible?'隐藏':'显示'} ${esc(l.name)}">${icon(l.visible?'eye':'eyeOff')}</button></div>`).join('')}</div><div class="asset-note">${icon('layers')}列表顶部的图层位于画面最上方。</div>`;}
}
const nfield=(prop,label,value,min=-10000,max=10000,step=1)=>`<label class="field"><span>${label}</span><input type="number" data-prop="${prop}" aria-label="${prop==='x'?'横向位置':prop==='y'?'纵向位置':prop==='w'?'对象宽度':prop==='h'?'对象高度':label}" value="${Math.round(value*100)/100}" min="${min}" max="${max}" step="${step}"></label>`;
const colorField=(prop,value,label='颜色')=>`<div class="color-control"><input type="color" data-prop="${prop}" value="${value}" aria-label="${label}"><input type="text" data-hex="${prop}" value="${value.toUpperCase()}" aria-label="${label}十六进制" maxlength="7"><span>HEX</span></div>`;
const rangeField=(prop,value,min,max,label,suffix='')=>`<label class="property-label">${label}</label><div class="range-row"><input type="range" data-prop="${prop}" min="${min}" max="${max}" value="${value}" aria-label="${label}"><output>${value}${suffix}</output></div>`;
const section=(title,body,extra=icon('chevronDown'))=>`<section class="property-section"><div class="property-title">${title}${extra}</div>${body}</section>`;
function renderInspector(){if(tool==='region'){$('#inspector').innerHTML=`<div class="inspector-header"><strong>区域清除</strong><span>Delete 填充</span></div>${section('背景颜色',backgroundSwatches())}${section('区域选择',region?`<div class="field-grid">${['x','y','w','h'].map(k=>`<label class="field"><span>${k.toUpperCase()}</span><input type="number" data-region="${k}" min="${k==='w'||k==='h'?1:0}" value="${region[k]}" aria-label="选区${({x:'横坐标',y:'纵坐标',w:'宽度',h:'高度'})[k]}"></label>`).join('')}</div>`:'<p class="panel-subtitle">在画布上拖动，选择要填充的矩形区域。</p>')}<div class="property-section"><button class="button primary" data-action="fill-region" ${region?'':'disabled'}>填充为背景色 · Delete</button><p class="panel-subtitle" style="margin:15px 0 0">框内区域将变为当前背景色，可撤销。Esc 取消区域选择。</p></div>`;return;}if(selectedIds.size>1){$('#inspector').innerHTML=`<div class="inspector-header"><strong>多选元素</strong><span>${selectedIds.size} 个元素</span></div><div class="property-section"><p>已选中 ${selectedIds.size} 个元素</p><p class="panel-subtitle">拖动任一选中元素可整体移动。Shift + 点击增减选择；方向键微调，Delete 删除。锁定或隐藏的图层不参与全选与框选。</p><div class="inspector-actions"><button data-action="duplicate">${icon('copy')}复制所选</button><button data-action="delete">${icon('trash')}删除所选</button></div><button class="button outline" data-action="deselect">取消选择</button></div>`;return;}const original=selected(),actual=original?.backgroundFill?{...original,fill:doc.background}:original,l=actual&&textRange&&actual.type==='text'?{...actual,...actual.charStyles?.[textRange.start]}:actual,panel=$('#inspector');if(!l){panel.innerHTML=`<div class="inspector-header"><strong>画布设置</strong><span>CANVAS</span></div>${section('画布尺寸',`<div class="field-grid"><label class="field"><span>W</span><input data-doc="width" type="number" min="1" max="16384" value="${doc.width}" aria-label="画布宽度"></label><label class="field"><span>H</span><input data-doc="height" type="number" min="1" max="16384" value="${doc.height}" aria-label="画布高度"></label></div>`)}${section('背景颜色',`${backgroundSwatches()}<div class="color-control" style="margin-top:12px"><input type="color" data-doc="background" value="${doc.background}" aria-label="画布背景色"><span>${doc.background.toUpperCase()}</span></div>`)}<div class="empty-state">${icon('cursor')}<br>选择一个元素<br>开始你的自由创作</div>`;return;}
 const kind=l.type==='text'?'文字':l.type==='image'?'图片':l.type==='path'?'画笔':'图形';
 let html=`<div class="inspector-header"><strong>${kind}属性</strong><span>${textRange?'局部样式':l.locked?'已锁定':'已选中 1 个元素'}</span></div>`;
 html+=section('位置与尺寸',`<div class="field-grid">${nfield('x','X',l.x)}${nfield('y','Y',l.y)}${nfield('w','W',l.w,1,16384)}${nfield('h','H',l.h,1,16384)}</div><div class="field-grid" style="margin-top:8px">${nfield('rotation','↻',l.rotation,-360,360)}<button class="field" data-action="toggle-lock">${icon(l.locked?'lock':'unlock')}<span>${l.locked?'解锁图层':'锁定图层'}</span></button></div><div class="align-buttons" style="margin-top:9px"><button data-action="align-left" title="画布左对齐">${icon('alignLeft')}</button><button data-action="align-center" title="画布水平居中">${icon('alignH')}</button><button data-action="align-right" title="画布右对齐">${icon('alignRight')}</button><button data-action="align-middle" title="画布垂直居中">${icon('alignV')}</button></div>`);
 if(l.type==='text'){
 html+=section('文字排版',`<select data-prop="fontFamily" class="full-select" aria-label="字体">${fonts.concat((doc.fonts||[]).map(f=>[f.family,f.name])).map(([v,n])=>`<option value="${v}" ${l.fontFamily===v?'selected':''}>${esc(n)}</option>`).join('')}</select><div class="field-grid" style="margin-top:8px">${nfield('fontSize','字号',l.fontSize,6,500)}<label class="field"><select data-prop="align" aria-label="文字对齐"><option value="left" ${l.align==='left'?'selected':''}>左对齐</option><option value="center" ${l.align==='center'?'selected':''}>居中</option><option value="right" ${l.align==='right'?'selected':''}>右对齐</option></select></label></div><div class="style-buttons"><button class="${l.bold?'active':''}" data-toggle="bold" title="加粗" aria-label="加粗" aria-pressed="${l.bold}"><b>B</b></button><button class="${l.italic?'active':''}" data-toggle="italic" title="斜体" aria-label="斜体"><i>I</i></button><button class="${l.underline?'active':''}" data-toggle="underline" title="下划线" aria-label="下划线"><u>U</u></button><button class="${l.strike?'active':''}" data-toggle="strike" title="删除线" aria-label="删除线"><s>S</s></button></div><div class="field-grid">${nfield('lineHeight','行距',l.lineHeight,.6,5,.1)}${nfield('letterSpacing','字距',l.letterSpacing,-10,100,.5)}</div><div style="margin-top:8px">${nfield('paragraphSpacing','段距',l.paragraphSpacing,0,200)}</div><label class="property-label">${textRange?`已选中 ${textRange.end-textRange.start} 个字符 · 设置局部样式`:'文字颜色'}</label>${colorField('fill',l.fill,'文字颜色')}<p class="font-hint">等线、微软雅黑使用本机已安装字体；未安装时使用思源黑体。可导入自己的字体文件。</p><div class="property-label" style="display:flex;justify-content:space-between">文字内容<button class="mini-link" data-action="font">${icon('plus')}导入字体</button></div><textarea class="text-content" data-prop="text" aria-label="文字内容" spellcheck="false">${esc(l.text)}</textarea><div style="font-size:9px;color:#a8af9e;margin-top:5px">选中部分文字，可单独修改样式</div>`);
 }else if(l.type==='image'){
 html+=section('图片调整',rangeField('brightness',l.brightness,0,200,'亮度','%')+rangeField('contrast',l.contrast,0,200,'对比度','%')+rangeField('saturation',l.saturation,0,200,'饱和度','%')+`<div class="style-buttons"><button data-action="flip-x" title="水平翻转">${icon('flip')} 水平翻转</button><button data-action="flip-y" title="垂直翻转">${icon('rotate')} 垂直翻转</button></div>`);
 html+=section('裁切与圆角',rangeField('cropX',l.cropX??50,0,100,'横向取景','%')+rangeField('cropY',l.cropY??50,0,100,'纵向取景','%')+rangeField('radius',l.radius,0,400,'圆角','px')+`<label class="check-row"><input type="checkbox" data-prop="topRound" ${l.topRound?'checked':''}>仅顶部圆角</label>`);
 }else{
 if(l.type==='path'){html+=section('画笔颜色',colorField('fill',l.fill,'画笔颜色'));}
 else if(l.shape!=='line'&&l.shape!=='lineArrow'){html+=section('填充',`<label class="check-row" style="margin-top:0"><input type="checkbox" data-prop="fillEnabled" ${l.fillEnabled!==false?'checked':''}>启用填充</label>`+(l.fillEnabled!==false?`<div style="margin-top:10px">${colorField('fill',l.fill,'填充颜色')}</div><label class="check-row"><input type="checkbox" data-prop="gradient" ${l.gradient?'checked':''}>渐变填充</label>${l.gradient?`<div style="margin-top:9px">${colorField('gradientColor',l.gradientColor||'#e8bda4','渐变终点颜色')}</div>`:''}`:'<p class="font-hint">空心图形，仅显示描边。</p>'));}
 if(l.type==='shape')html+=section('描边与圆角',colorField('stroke',l.stroke,'描边颜色')+rangeField('strokeWidth',l.strokeWidth,l.shape==='line'||l.shape==='lineArrow'?1:0,40,'描边粗细','px')+(l.shape==='rect'||l.shape==='roundrect'?rangeField('radius',l.radius,0,200,'圆角','px'):'')+`<label class="check-row"><input type="checkbox" data-prop="dashed" ${l.dashed?'checked':''}>虚线描边</label>`);
 else html+=section('画笔粗细',rangeField('strokeWidth',l.strokeWidth,1,100,'粗细','px'));
 }
 html+=section('外观',rangeField('opacity',Math.round(l.opacity*100),0,100,'不透明度','%')+rangeField('shadow',l.shadow,0,70,'阴影','px'));
 html+=`<div class="inspector-actions"><button data-action="duplicate">${icon('copy')}复制</button><button class="danger" data-action="delete">${icon('trash')}删除</button></div><div class="inspector-tip">${l.type==='text'?'双击文字框内任意位置，即可编辑':'拖动调整位置，拖动角点调整尺寸'}<br>Shift + 拖动角点 · 保持原始比例</div>`;
 panel.innerHTML=html;if(l.type==='text'){const heightInput=$('[data-prop="h"]',panel);heightInput.readOnly=true;heightInput.title='文字高度根据内容自动计算；拖动角点可等比缩放文字';}
}
function refresh(){render();positionCanvas();renderAssets();renderInspector();$('#documentName').value=doc.name;updateHistory();}
