window.addEventListener('keydown',e=>{if($('#modal').open)return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&key==='s'){e.preventDefault();finishTextEdit();commit();saveProject();return;}if(mod&&key==='a'&&!e.target.matches('input,textarea,[contenteditable=true]')){e.preventDefault();finishTextEdit();setTool('select');setSelection(doc.layers.filter(l=>l.visible&&!l.locked).map(l=>l.id));textRange=null;render();renderInspector();if(activePanel==='layers')renderAssets();return;}if(isTyping(e.target))return;if(mod&&key==='z'){e.preventDefault();if(drag?.type==='shape'){cancelShapeDrawing();return;}e.shiftKey?redo():undo();return;}if(mod&&key==='y'){e.preventDefault();redo();return;}if(mod&&key==='s'){e.preventDefault();saveProject();return;}if(mod&&key==='d'){e.preventDefault();duplicate();return;}if(mod&&key==='c'&&selected()){clipboard=selectedLayers().filter(l=>!l.locked).map(clone);e.preventDefault();return;}if(mod&&key==='v'&&clipboard){const copies=clipboard.map(l=>({...clone(l),id:uid(),x:l.x+24,y:l.y+24,locked:false}));doc.layers.push(...copies);setSelection(copies.map(l=>l.id));commit();refresh();e.preventDefault();return;}if(e.code==='Space'){e.preventDefault();spaceHeld=true;viewport.classList.add('pan-cursor');return;}if(key==='v')setTool('select');if(key==='h')setTool('hand');if(key==='m')setTool('marquee');if(key==='r'){$('#regionTool').click();}if(key==='b')setTool('brush');if(key==='t')addText();if(key==='delete'||key==='backspace'){e.preventDefault();if(tool==='region'){fillRegion();return;}remove();}if(key==='escape'){setTool('select');select(null);$('#assetPanel').classList.remove('mobile-open');$('#inspector').classList.remove('mobile-open');}const l=selected();if(l&&!l.locked&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const s=e.shiftKey?10:1;for(const layer of selectedLayers().filter(o=>!o.locked)){if(e.key==='ArrowLeft')layer.x-=s;if(e.key==='ArrowRight')layer.x+=s;if(e.key==='ArrowUp')layer.y-=s;if(e.key==='ArrowDown')layer.y+=s;}commit();render();renderInspector();}});
window.addEventListener('keyup',e=>{if(e.code==='Space'){spaceHeld=false;viewport.classList.toggle('pan-cursor',tool==='hand');}});window.addEventListener('blur',()=>{spaceHeld=false;viewport.classList.toggle('pan-cursor',tool==='hand');});
function showModal(title,body){finishTextEdit();$('#modalContent').innerHTML=`<div class="modal-head"><h2>${title}</h2><button id="closeModal" aria-label="关闭">×</button></div><div class="modal-body">${body}</div>`;$('#closeModal').onclick=()=>$('#modal').close();$('#modal').showModal();}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function dimensionDialog(isNew){showModal(isNew?'一张新画布，无限种可能':'调整画布',`<p>${isNew?'先选一个舒服的尺寸，让灵感有地方发生。新建前可通过「文件」保存当前项目。':'调整画布尺寸不会缩放现有图层，你可以继续自由排版。'}</p><label class="property-label">常用尺寸</label><select id="sizePreset" class="full-select"><option value="custom">自定义尺寸</option><option value="800,1000">竖版海报 · 800 × 1000</option><option value="1080,1080">方形配图 · 1080 × 1080</option><option value="1920,1080">横版封面 · 1920 × 1080</option><option value="1080,1920">手机壁纸 · 1080 × 1920</option></select><div class="field-grid form-row"><label class="field"><span>宽</span><input id="newWidth" type="number" min="1" max="16384" value="${doc.width}" aria-label="新画布宽度"><span>px</span></label><label class="field"><span>高</span><input id="newHeight" type="number" min="1" max="16384" value="${doc.height}" aria-label="新画布高度"><span>px</span></label></div><label class="property-label">背景颜色</label><div class="color-control"><input id="newBackground" type="color" value="${isNew?'#ffffff':doc.background}" aria-label="新画布背景"><span>选择喜欢的底色</span><button id="modalWhite" class="white-background-button">白色</button></div><button class="button primary" id="confirmCanvas">${isNew?'创建新画布':'应用更改'} ${icon('arrowUpRight')}</button>`);
 $('#modalWhite').onclick=()=>{$('#newBackground').value='#ffffff';};
 $('#sizePreset').onchange=e=>{if(e.target.value!=='custom'){const [w,h]=e.target.value.split(',');$('#newWidth').value=w;$('#newHeight').value=h;}};$('#confirmCanvas').onclick=()=>{const width=Number($('#newWidth').value),height=Number($('#newHeight').value);if(!validCanvasSize(width,height)){toast('宽高需为 1–16384 的整数，且总面积不超过 6400 万像素');return;}if(isNew){doc={version:1,name:'未命名作品',width:Math.round(width),height:Math.round(height),background:$('#newBackground').value,layers:[],fonts:clone(doc.fonts)};region=null;setTool('select');setSelection([]);}else{doc.width=Math.round(width);doc.height=Math.round(height);doc.background=$('#newBackground').value;}commit();refresh();fit();$('#modal').close();toast(isNew?'新画布已准备好':'画布已更新');};}
$('#newProject').onclick=()=>dimensionDialog(true);$('#canvasSettings').onclick=()=>dimensionDialog(false);
function download(blob,filename){const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function safeName(){return doc.name.replace(/[<>:"/\\|?*]/g,'_').slice(0,80)||'图绎作品';}
function saveProject(){download(new Blob([JSON.stringify(doc)],{type:'application/json'}),safeName()+'.figlyph');toast('项目已保存 · 可保留所有图层继续编辑');}
$('#projectMenu').onclick=()=>{showModal('你的创作文件',`<p>作品只在当前浏览器自动保存。下载项目文件，可以备份并在其他设备继续编辑。</p><div class="file-options"><a href="/editor/downloads/figlyph.zip?v=20261017-9" download>下载编辑器压缩包 ↗</a><button id="saveProject">${icon('download')}保存项目文件 <span style="margin-left:auto;color:#aaa">⌘ / Ctrl S</span></button><button id="openProject">${icon('folder')}打开项目文件</button><button id="showCanvas">${icon('frame')}画布尺寸与背景</button></div>`);$('#saveProject').onclick=()=>{saveProject();$('#modal').close();};$('#openProject').onclick=()=>{$('#projectInput').click();};$('#showCanvas').onclick=()=>{$('#modal').close();select(null);dimensionDialog(false);};};
function validateDocument(d){if(!d||d.version!==1||!validCanvasSize(d.width,d.height)||!/^#[0-9a-f]{6}$/i.test(d.background)||!Array.isArray(d.layers)||d.layers.length>500||!Array.isArray(d.fonts)||d.fonts.length>50||typeof d.name!=='string')return false;
 const ids=new Set();for(const l of d.layers){if(!l||typeof l.id!=='string'||ids.has(l.id)||!['text','shape','image','path'].includes(l.type)||typeof l.name!=='string')return false;ids.add(l.id);for(const p of ['x','y','w','h','rotation','opacity','shadow','radius','strokeWidth'])if(!Number.isFinite(l[p])||Math.abs(l[p])>100000)return false;if(l.w<=0||l.h<=0||l.opacity<0||l.opacity>1||typeof l.visible!=='boolean'||typeof l.locked!=='boolean'||!/^#[0-9a-f]{6}$/i.test(l.fill)||!/^#[0-9a-f]{6}$/i.test(l.stroke))return false;
 if(l.type==='text'){if(typeof l.text!=='string'||l.text.length>50000||typeof l.fontFamily!=='string'||/["\\]/.test(l.fontFamily)||!l.charStyles||typeof l.charStyles!=='object')return false;for(const p of ['fontSize','lineHeight','letterSpacing','paragraphSpacing'])if(!Number.isFinite(l[p]))return false;if(l.fontSize<1||l.fontSize>1000||l.lineHeight<=0||!['left','center','right'].includes(l.align))return false;for(const style of Object.values(l.charStyles)){if(!style||typeof style!=='object')return false;for(const key of Object.keys(style)){if(!['fontSize','fontFamily','fill','bold','italic','underline','strike'].includes(key))return false;if(key==='fontSize'&&(!Number.isFinite(style[key])||style[key]<1||style[key]>1000))return false;if(key==='fill'&&!/^#[0-9a-f]{6}$/i.test(style[key]))return false;if(key==='fontFamily'&&(typeof style[key]!=='string'||/["\\]/.test(style[key])))return false;}}}
 if(l.backgroundFill!==undefined&&(typeof l.backgroundFill!=='boolean'||l.type!=='shape'||l.shape!=='rect'||l.fillEnabled===false))return false;
 if(l.fillEnabled!==undefined&&typeof l.fillEnabled!=='boolean')return false;
 if(l.gradientColor&&!/^#[0-9a-f]{6}$/i.test(l.gradientColor))return false;
 if(l.type==='shape'&&!Object.keys(shapeNames).concat('sparkle').includes(l.shape))return false;
 if(l.type==='image'){if(typeof l.src!=='string'||!(/^(data:image\/(png|jpeg|webp|gif);base64,|\/images\/[a-z0-9_.-]+$)/i.test(l.src)))return false;for(const p of ['brightness','contrast','saturation','cropX','cropY'])if(!Number.isFinite(l[p])||l[p]<0||l[p]>200)return false;}
 if(l.type==='path'&&(!Array.isArray(l.points)||l.points.length>100000||!l.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))))return false;
 }return d.fonts.every(f=>f&&typeof f.family==='string'&&/^Custom[a-z0-9]+$/i.test(f.family)&&typeof f.name==='string'&&typeof f.data==='string'&&/^data:(font\/[^;,]+|application\/[^;,]+|);base64,/i.test(f.data));}
$('#projectInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>80*1024*1024)throw new Error();const data=JSON.parse(await file.text());if(!validateDocument(data))throw new Error();doc=data;region=null;setTool('select');setSelection([]);textRange=null;await loadFonts();commit();refresh();fit();$('#modal').close();toast('项目已打开，继续你的创作');}catch{toast('无法打开：请选择有效的图绎项目文件');}e.target.value='';});
$('#exportButton').onclick=()=>{let format='png';showModal('让作品，走出画布',`<p>每一个灵感，都值得被看见。</p><div class="format-options"><button class="active" data-format="png">PNG</button><button data-format="jpeg">JPG</button><button data-format="webp">WebP</button></div><label class="property-label">导出尺寸</label><select id="exportScale" class="full-select"><option value="1">原始尺寸 · ${doc.width} × ${doc.height} px</option><option value="2" ${doc.width*doc.height>4000000?'disabled':''}>2 倍清晰 · ${doc.width*2} × ${doc.height*2} px</option><option value="0.5">轻量尺寸 · ${Math.round(doc.width/2)} × ${Math.round(doc.height/2)} px</option></select><label class="check-row" id="transparentRow"><input type="checkbox" id="transparentExport">透明背景</label><label class="property-label">图片质量</label><div class="range-row"><input type="range" id="exportQuality" min="20" max="100" value="95" aria-label="导出质量"><output>95%</output></div><button class="button primary" id="downloadImage">${icon('download')}下载图片</button><p style="font-size:10px;color:#a1a995;text-align:center">导出不包含编辑边框与辅助线</p>`);
 $$('[data-format]').forEach(el=>el.onclick=()=>{format=el.dataset.format;$$('[data-format]').forEach(b=>b.classList.toggle('active',b===el));$('#transparentRow').style.display=format==='jpeg'?'none':'';});$('#exportQuality').oninput=e=>e.target.nextElementSibling.textContent=e.target.value+'%';
 $('#downloadImage').onclick=async()=>{const btn=$('#downloadImage');btn.disabled=true;btn.textContent='正在准备作品…';try{for(const l of doc.layers)if(l.type==='image'&&l.visible)getImage(l.src);await Promise.all(doc.layers.filter(l=>l.type==='image'&&l.visible).map(l=>imageCache.has(l.src)?Promise.resolve():imagePromises.get(l.src)));await document.fonts.ready;const scale=Number($('#exportScale').value),out=document.createElement('canvas');out.width=Math.round(doc.width*scale);out.height=Math.round(doc.height*scale);const c=out.getContext('2d');c.scale(scale,scale);paint(c,format!=='jpeg'&&$('#transparentExport').checked);const blob=await new Promise(resolve=>out.toBlob(resolve,'image/'+format,Number($('#exportQuality').value)/100));if(!blob)throw new Error();download(blob,safeName()+'.'+(format==='jpeg'?'jpg':format));$('#modal').close();toast('作品已导出，分享你的灵感吧');}catch{btn.disabled=false;btn.innerHTML=icon('download')+'重试导出';toast('导出失败，请检查图片是否完整加载');}};
};
$('#helpButton').onclick=()=>showModal('给创作一点小帮助',`<p>选择基础图形后，在画布上拖动绘制；按住 Shift 等比绘制或限定线条角度，Esc 取消。双击文字框即可直接编辑。右侧面板可以精细调整样式，图层面板可以控制前后顺序。</p><div class="shortcut-list">${[['选择工具 / 框选','V / M'],['区域清除 / 背景色填充','R / Delete'],['全选可编辑元素','⌘ / Ctrl A'],['增减选择 / 追加框选','Shift + 点击 / 框选'],['移动画布 / 临时移动','H / 空格'],['自由画笔','B'],['添加文字','T'],['撤销 / 重做','⌘ / Ctrl Z · Shift Z'],['复制图层','⌘ / Ctrl D'],['复制 / 粘贴图层','⌘ / Ctrl C / V'],['保存项目','⌘ / Ctrl S'],['移动元素 / 快速移动','方向键 / Shift + 方向键'],['删除选中图层','Delete / Backspace'],['缩放画布','⌘ / Ctrl + 滚轮'],['保持比例缩放','Shift + 拖动角点']].map(([a,b])=>`<span>${a}</span><kbd>${b}</kbd>`).join('')}</div><p style="margin-top:20px">图片可拖入或直接粘贴。自动保存仅限当前浏览器；重要作品记得保存项目文件。</p>`);
try{const saved=localStorage.getItem(STORAGE);if(saved){const parsed=JSON.parse(saved);if(validateDocument(parsed)){doc=parsed;setSelection([doc.layers.find(l=>l.type==='text')?.id]);}}}catch{}
document.fonts.addEventListener('loadingdone',()=>{render();persist();if(!isTyping(document.activeElement))renderInspector();});
commit();refresh();fit();loadFonts();new ResizeObserver(()=>fit()).observe(viewport);
